import React from 'react';
import { statusList } from 'views/admin/Activities';
import { getAdmissionStatusMeta } from './admissionStatus';

// A pill with the status icon, tinted in the status colour.
export const Pill = ({ color, Icon, children, style }) => (
  <span
    style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: 5,
      padding: '3px 10px 3px 7px',
      borderRadius: 14,
      fontSize: 12,
      fontWeight: 'bold',
      whiteSpace: 'nowrap',
      color,
      background: `${color}1a`,
      border: `1px solid ${color}40`,
      ...style,
    }}>
    {Icon && <Icon style={{ fontSize: 15 }} />}
    {children}
  </span>
);

const AdmissionStatusBadge = ({ status }) => {
  const { Icon, color } = getAdmissionStatusMeta(status);
  const label = statusList.find(item => item.value === status)?.label || status || '--';
  return (
    <Pill color={color} Icon={Icon}>
      {label}
    </Pill>
  );
};

export default AdmissionStatusBadge;
