import React from 'react';
import { connect } from 'react-redux';
import { Card, CardBody, Table, Row, Col } from 'reactstrap';
import { admissionTableHead } from 'variables/general';
import {
  fetchAllAdmissionsService,
  saveAdmissionService,
  fetchAdmissionService,
  updateAdmissionService,
  deleteAdmissionService,
  fetchAdmissionByNumberAndIdService,
  addAdmissionBillService,
  showAdmissionReceiptService,
  showPlainAdmissionFormService,
} from 'actions/admin/admissions';
import AdmissionList from './components/AdmissionList.jsx';
import AdmissionFormModal from './components/AdmissionFormModal.jsx';
import AdmissionPaymentModal from './components/AdmissionPaymentModal.jsx';
import AdmissionStatusCards from './components/AdmissionStatusCards.jsx';
import Page from '../Common/Pagination.jsx';
import { getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast } from '../../../actions/admin/auth.js';
import CustomButton from '../../../components/CustomButton.jsx';
import { fetchBatchCourseService } from 'actions/admin/courses.js';
import { fetchSchoolBatchedHandler } from '../../../actions/admin/batches';
import { formResMessage } from '../../../utils/commonFunc.js';

class AdmissionPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      status: 'PENDING',
      batchList: [],
      paymentAdmission: null,
      receiptAdmissionId: null,
      plainFormLoading: false,
    };
  }

  fetchSchoolBatches = async schoolId => {
    try {
      const res = schoolId
        ? await fetchSchoolBatchedHandler({
            schoolId,
            token: this.props.loggedUserToken,
          })
        : {};
      if (res?.data) this.setState(prevState => ({ ...prevState, batchList: res?.data }));
    } catch (err) {
      console.lg('err', err);
    }
  };

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    const batch = getGlobalCurrentBatchUtils();
    if (batch?.batchId) {
      this.props.fetchBatchCourse({ batchId: batch.batchId, token: this.props.loggedUserToken });
    }
    if (globalSchool) {
      this.fetchSchoolBatches(globalSchool?.schoolId);
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllAdmissions();
      });
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  fetchAllAdmissions = (status = this.state.status) => {
    this.props.fetchAllAdmissions({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
      pageParams: this.state.pageParams,
      status,
    });
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  saveAdmission = ({ paymentAmount, paymentNote, ...data }) => {
    const batch = getGlobalCurrentBatchUtils();
    data.schoolId = this.state.schoolId;
    data.batchId = data.batchId || batch.batchId;
    return this.props
      .saveAdmission({
        postData: data,
        token: this.props.loggedUserToken,
      })
      .then(res => {
        if (!paymentAmount) return res;
        // The admission is already saved at this point, so a failed payment must not fail the whole save: it can
        // be added again from the list.
        return addAdmissionBillService({
          admissionId: res?.data?.admissionId,
          amount: paymentAmount,
          note: paymentNote,
          token: this.props.loggedUserToken,
        })
          .then(() => res)
          .catch(err => {
            this.showWarning(
              `Admission added, but the payment could not be saved (${formResMessage(
                err
              )}). Use "Add payment" in the list.`,
              'warning'
            );
            return res;
          });
      });
  };

  openPaymentModal = admission => this.setState({ paymentAdmission: admission });

  closePaymentModal = () => this.setState({ paymentAdmission: null });

  savePayment = ({ amount, note }) => {
    const { paymentAdmission } = this.state;
    return addAdmissionBillService({
      admissionId: paymentAdmission.admissionId,
      amount,
      note,
      token: this.props.loggedUserToken,
    }).then(() => {
      this.setState({ paymentAdmission: null });
      this.showWarning('Payment added successfully', 'success');
      this.fetchAllAdmissions();
    });
  };

  openPlainForm = () => {
    this.setState({ plainFormLoading: true });
    this.props
      .showPlainAdmissionForm({ schoolId: this.state.schoolId, token: this.props.loggedUserToken })
      .catch(err => this.showWarning(err.message, 'error'))
      .finally(() => this.setState({ plainFormLoading: false }));
  };

  viewReceipt = (admission, download) => {
    this.setState({ receiptAdmissionId: admission.admissionId });
    this.props
      .showAdmissionReceipt({
        schoolId: this.state.schoolId,
        billId: admission.customBillId,
        applicationNo: admission.applicationNo,
        download,
        token: this.props.loggedUserToken,
      })
      .catch(err => this.showWarning(err.message, 'error'))
      .finally(() => this.setState({ receiptAdmissionId: null }));
  };

  fetchAdmission = admissionId => {
    return this.props
      .fetchAdmission({ admissionId, token: this.props.loggedUserToken })
      .then(() => this.formModalOpen());
  };

  updateAdmission = data => {
    return this.props.updateAdmission({
      admissionId: data.admissionId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  admissionUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'Admin added successfully' : 'Admin Updated successfully', 'success');
    this.fetchAllAdmissions();
  };

  deleteAdmission = admissionId => {
    return this.props.deleteAdmission({ admissionId, token: this.props.loggedUserToken }).then(() => {
      // this.deleteCancel();
      this.fetchAllAdmissions();
    });
  };

  fetchPageData = page => {
    this.setState(
      {
        pageParams: {
          ...this.state.pageParams,
          page,
        },
      },
      () => {
        // window.scrosllTo(0, this.topRef.current.offsetTop)
        // let wHeight = window.innerHeight;
        // window.scrollY = wHeight;
        this.fetchAllAdmissions();
      }
    );
  };

  viewAdmission = (admissionId, phoneNumber) => {
    this.props
      .fetchAdmission({
        admissionId,
        phoneNumber,
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        const win = window.open(`/user/admission-form/${this.state.schoolId}/${phoneNumber}/${admissionId}`, '_blank');
        win.focus();
      });
  };

  handleSelectChange = status => {
    this.setState(prevState => ({ ...prevState, status }));
    this.fetchAllAdmissions(status);
  };

  render() {
    const { isModalOpen, status, batchList, paymentAdmission, receiptAdmissionId, plainFormLoading } = this.state;
    const {
      loggedUserRole,
      admissionData,
      schools,
      admission,
      currentBatch,
      batchCourseList,
      // admissionByNumberAndId,
      // test
    } = this.props;
    const noDataFoundDiv = (
      <tr className="text-center">
        <td colSpan="8" style={{ paddingTop: 30, fontWeight: 'bold' }}>
          NO DATA FOUND
        </td>
      </tr>
    );
    return (
      <div className="content">
        <Row className="mb-3">
          <Col xs={12} md>
            <AdmissionStatusCards status={status} onChange={this.handleSelectChange} />
          </Col>
          <Col xs={12} md="auto" className="d-flex align-items-start justify-content-md-end mt-2 mt-md-0">
            <CustomButton
              style={{ whiteSpace: 'nowrap', marginRight: 8 }}
              variant="outlined"
              color="default"
              onClick={this.openPlainForm}
              disabled={plainFormLoading}
              loading={plainFormLoading}
              name="Print admission form"
            />
            <CustomButton
              style={{ whiteSpace: 'nowrap' }}
              variant="contained"
              color="secondary"
              onClick={this.formModalOpen}
              name="Add New"
            />
          </Col>
        </Row>
        <Row>
          <Col xs={12}>
            <Card>
              <CardBody>
                <Table size="sm" responsive>
                  <thead className="text-primary">
                    <tr>
                      {admissionTableHead.map((prop, key) => {
                        if (key === admissionTableHead.length - 1)
                          return (
                            <th key={key} className="text-center">
                              {prop}
                            </th>
                          );
                        return <th key={key}>{prop}</th>;
                      })}
                    </tr>
                  </thead>
                  <tbody>
                    {admissionData?.content?.length > 0
                      ? admissionData.content.map(admissionItem => {
                          return (
                            <AdmissionList
                              key={admissionItem.admissionId}
                              admissionItem={admissionItem}
                              fetchAdmission={this.fetchAdmission}
                              deleteAdmission={this.deleteAdmission}
                              viewAdmission={this.viewAdmission}
                              addPayment={this.openPaymentModal}
                              viewReceipt={this.viewReceipt}
                              isReceiptLoading={receiptAdmissionId === admissionItem.admissionId}
                            />
                          );
                        })
                      : noDataFoundDiv}
                  </tbody>
                </Table>
                {admissionData?.content?.length > 0 && (
                  <>
                    <hr />
                    <Page {...admissionData} fetchPageData={this.fetchPageData} />
                  </>
                )}
              </CardBody>
            </Card>
          </Col>
        </Row>
        <AdmissionFormModal
          isModalOpen={isModalOpen}
          schools={schools}
          formModalCloseProp={this.formModalClose}
          saveAdmission={this.saveAdmission}
          admission={admission}
          updateAdmission={this.updateAdmission}
          admissionUpdateSuccess={this.admissionUpdateSuccess}
          currentBatch={currentBatch}
          batchCourseList={batchCourseList}
          loggedUserRole={loggedUserRole}
          batchList={batchList}
        />
        <AdmissionPaymentModal
          isOpen={!!paymentAdmission}
          admission={paymentAdmission}
          onSubmit={this.savePayment}
          onClose={this.closePaymentModal}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserRole: state.auth?.loggedUserRole,
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    schools: state.schools.schoolList,
    batchCourseList: state.courses?.batchCourseList,
    admissionData: state.admissions.admissionData,
    admission: state.admissions.admission,
    currentBatch: state.batches?.currentBatch,
    admissionByNumberAndId: state.admissions.admissionByNumberAndId,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchBatchCourse: data => dispatch(fetchBatchCourseService(data)),
    fetchAllAdmissions: data => dispatch(fetchAllAdmissionsService(data)),
    saveAdmission: data => dispatch(saveAdmissionService(data)),
    fetchAdmission: data => dispatch(fetchAdmissionService(data)),
    updateAdmission: data => dispatch(updateAdmissionService(data)),
    deleteAdmission: data => dispatch(deleteAdmissionService(data)),
    fetchAdmissionByNumberAndId: data => dispatch(fetchAdmissionByNumberAndIdService(data)),
    showAdmissionReceipt: data => dispatch(showAdmissionReceiptService(data)),
    showPlainAdmissionForm: data => dispatch(showPlainAdmissionFormService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(AdmissionPage);
