import React from 'react';
import colors from 'config/colors';
import { statusList } from 'views/admin/Activities';
import { getAdmissionStatusMeta } from './admissionStatus';

// The status quick filters of the admissions list: one row of pills. They are all the app's accent colour (the status colours belong to
// the badges in the table), the chosen one is filled, and there are no counts because the list is paged.
const AdmissionStatusCards = ({ status, onChange }) => (
  <div
    style={{
      display: 'flex',
      alignItems: 'center',
      flexWrap: 'nowrap',
      gap: 8,
      overflowX: 'auto',
      padding: '2px 2px 6px',
    }}>
    <span style={{ flex: '0 0 auto', fontSize: 11, fontWeight: 'bold', textTransform: 'uppercase', color: '#8b95a1' }}>
      Quick filter
    </span>
    {statusList.map(item => {
      const { Icon } = getAdmissionStatusMeta(item.value);
      const active = status === item.value;
      const select = () => !active && onChange(item.value);
      return (
        <div
          key={item.value}
          role="button"
          tabIndex={0}
          aria-pressed={active}
          onClick={select}
          onKeyDown={e => e.key === 'Enter' && select()}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 5,
            flex: '0 0 auto',
            padding: '5px 14px 5px 10px',
            cursor: 'pointer',
            borderRadius: 20,
            border: `1px solid ${active ? colors.accent : '#dfe3ea'}`,
            background: active ? colors.accent : '#fff',
            color: active ? '#fff' : '#5c6675',
            boxShadow: active ? '0 2px 8px rgba(123,31,162,0.25)' : 'none',
            transition: 'all .15s',
          }}>
          <Icon style={{ fontSize: 16 }} />
          <span style={{ fontSize: 12, fontWeight: 'bold', whiteSpace: 'nowrap' }}>{item.label}</span>
        </div>
      );
    })}
  </div>
);

export default AdmissionStatusCards;
