import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

// The backend stores bill amounts as whole numbers and the note must fit its 500 character column.
export const MAX_PAYMENT_NOTE = 500;
export const isValidPaymentAmount = value => /^\d+$/.test(`${value}`.trim()) && Number(value) > 0;

// Records the admission payment for an admission that has none yet. onSubmit({ amount, note }) returns a promise.
const AdmissionPaymentModal = ({ isOpen, admission, onSubmit, onClose }) => {
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setAmount('');
      setNote('');
      setError('');
      setSaving(false);
    }
  }, [isOpen]);

  const handleSubmit = e => {
    e.preventDefault();
    if (!isValidPaymentAmount(amount)) {
      setError('Enter the amount as a whole number greater than zero');
      return;
    }
    setError('');
    setSaving(true);
    onSubmit({ amount: Number(amount), note }).catch(err => {
      setError(formResMessage(err));
      setSaving(false);
    });
  };

  return (
    <Modal isOpen={isOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>ADD PAYMENT</ModalHeader>
        <ModalBody>
          {admission && (
            <p className="mb-3">
              <b>{`${admission.firstName || ''} ${admission.lastName || ''}`.trim()}</b>
              {admission.applicationNo ? ` (${admission.applicationNo})` : ''}
            </p>
          )}
          {error && <div className="alert alert-danger">{error}</div>}
          <Row>
            <Col xs={12}>
              <FormGroup>
                <Label htmlFor="admissionPaymentAmount">
                  Amount<sup> *</sup>
                </Label>
                <Input
                  id="admissionPaymentAmount"
                  type="text"
                  inputMode="numeric"
                  value={amount}
                  onChange={e => setAmount(e.target.value.replace(/\D/g, '').slice(0, 9))}
                  placeholder="Enter amount..."
                />
              </FormGroup>
            </Col>
            <Col xs={12}>
              <FormGroup>
                <Label htmlFor="admissionPaymentNote">Note</Label>
                <Input
                  id="admissionPaymentNote"
                  type="textarea"
                  rows={3}
                  value={note}
                  onChange={e => setNote(e.target.value)}
                  placeholder="Optional..."
                  maxLength={MAX_PAYMENT_NOTE}
                />
              </FormGroup>
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            type="submit"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="secondary"
            name="Save"
            disabled={saving}
            loading={saving}
          />
          <CustomButton
            className="ml-2"
            type="reset"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="default"
            onClick={onClose}
            disabled={saving}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default AdmissionPaymentModal;
