import HourglassEmptyIcon from '@material-ui/icons/HourglassEmpty';
import AutorenewIcon from '@material-ui/icons/Autorenew';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import CancelIcon from '@material-ui/icons/Cancel';
import BlockIcon from '@material-ui/icons/Block';
import PauseCircleFilledIcon from '@material-ui/icons/PauseCircleFilled';

// Icon and colour of each admission status, shared by the filter cards (icon only) and the badge in the list (icon and colour).
export const ADMISSION_STATUS_META = {
  PENDING: { Icon: HourglassEmptyIcon, color: '#b26a00' },
  INPROGRESS: { Icon: AutorenewIcon, color: '#1565c0' },
  COMPLETED: { Icon: CheckCircleIcon, color: '#2e7d32' },
  REJECTED: { Icon: CancelIcon, color: '#c62828' },
  CANCELED: { Icon: BlockIcon, color: '#78909c' },
  HOLD: { Icon: PauseCircleFilledIcon, color: '#6d4c41' },
};

export const getAdmissionStatusMeta = status => ADMISSION_STATUS_META[status] || ADMISSION_STATUS_META.PENDING;
