import React from 'react';
import colors from 'config/colors';

// A small set of options as selectable chips (instead of radio buttons or a dropdown). The chosen one is filled in the accent colour;
// clicking it again does not clear it. `value` is compared as a string so booleans work too.
const ChoiceChips = ({ options, value, onChange, disabled = false }) => (
  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
    {options.map(option => {
      const active = `${value}` === `${option.value}`;
      return (
        <button
          key={`${option.value}`}
          type="button"
          disabled={disabled}
          aria-pressed={active}
          onClick={() => onChange(option.value)}
          style={{
            padding: '6px 14px',
            borderRadius: 18,
            fontSize: 13,
            fontWeight: 600,
            cursor: disabled ? 'not-allowed' : 'pointer',
            opacity: disabled ? 0.6 : 1,
            border: `1px solid ${active ? colors.accent : '#d5dae2'}`,
            background: active ? colors.accent : '#fff',
            color: active ? '#fff' : '#5c6675',
            transition: 'all .15s',
          }}>
          {option.label}
        </button>
      );
    })}
  </div>
);

export default ChoiceChips;
