import React, { useState, useEffect } from 'react';
import {
  Modal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Row,
  Col,
  Input,
  Label,
  FormGroup,
  InputGroup,
  InputGroupAddon,
  InputGroupText,
  // CustomInput
} from 'reactstrap';
import moment from 'moment';
import validator from 'validator';
import Select from 'react-select';
import DatePicker from 'react-datepicker';
import CustomButton from '../../../../components/CustomButton';
import colors from 'config/colors';
import { formCourseSelectList, formResMessage, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { statusList } from 'views/admin/Activities';
import constants from 'config/constants';
import CustomSelect from 'components/CustomSelect';
import ChoiceChips from './ChoiceChips';
import { MAX_PAYMENT_NOTE, isValidPaymentAmount } from './AdmissionPaymentModal';
// import { handleKeyNumberPress, handleKeyCharacterPress } from 'utils/commonFunc';

const relationTypes = [
  { label: 'Mother', value: 'MOTHER' },
  { label: 'Father', value: 'FATHER' },
  { label: 'Uncle', value: 'UNCLE' },
  { label: 'Friend', value: 'FRIEND' },
  // { label: 'Other', value: 'OTHER' }
];

const GENDERS = [
  { label: 'Male', value: 'MALE' },
  { label: 'Female', value: 'FEMALE' },
];

const YES_NO = [
  { label: 'Yes', value: true },
  { label: 'No', value: false },
];

const initialState = {
  data: {
    admissionId: 0,
    applicationNo: '', // Req
    schoolId: 0, // Req
    batchId: 0, // Req
    courseId: 0, // Req
    // Student
    firstName: '', // Req
    lastName: '', // Req
    acadYear: '',
    admissionYear: '',
    email: '',
    gender: '',
    dateOfBirth: '',
    birthPlace: '',
    bloodGroup: '',
    // category: '',
    // curriculumInterested: '',
    // hostelAccomodation: '',
    isPhysicallyChallenged: false,
    // mediumInstruction: '',
    motherTongue: '',
    nationality: '',
    // middleName: '',
    religion: '',
    // Guardian
    guardianName: '',
    guardianEmail: '', // Req
    phoneNumber: '', // Req
    education: '',
    income: 0,
    occupation: '',
    relation: '',
    // Additional
    remarks: '',
    staffCode: '',
    isStaffChild: false,
    status: 'PENDING',
    // Admission payment (new admissions only; optional)
    paymentAmount: '',
    paymentNote: '',
  },
  errors: {},
  loading: false,
};

const AdmissionFormModal = props => {
  const {
    isModalOpen,
    // schools,
    saveAdmission,
    updateAdmission,
    admissionUpdateSuccess,
    formModalCloseProp,
    admission,
    batchCourseList,
    loggedUserRole,
    batchList,
  } = props;
  const storeBatch = getGlobalCurrentBatchUtils();
  // a new admission starts on the current batch, which can be changed to a later one
  const stateObj = { ...initialState, data: { ...initialState.data, batchId: storeBatch?.batchId || 0 } };

  const [stateVal, setState] = useState(stateObj);

  const batchArr = batchList
    ?.filter(dto => dto?.startYear >= storeBatch?.startYear)
    .map(el => ({
      label: el.name,
      value: el.batchId,
      batchId: el.batchId,
    }));

  const courseArr = formCourseSelectList(batchCourseList);

  // useEffect(() => {
  //   if(schools && schools.length > 0) {
  //     let schoolArr = [];
  //     schools.forEach(item => {
  //       schoolArr.push({
  //         schoolId: item.schoolId,
  //         label: `${item.schoolCode} - ${item.schoolName}`,
  //         value: item.schoolId
  //       });
  //     });
  //     setState(prevState => ({ ...prevState, schoolArr: schoolArr }));
  //   }
  // },[schools]);

  useEffect(() => {
    if (admission && Object.keys(admission).length) {
      setState(prevState => ({
        ...prevState,
        data: admission,
      }));
    }
  }, [admission]);

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectItem,
      },
    }));
  };

  const handleDateChange = (name, date) => {
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [name]: moment(moment(date).format('YYYY-MM-DD HH:mm:ss')).valueOf() },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (!Object.keys(errors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      if (data.admissionId) {
        return updateAdmission(data)
          .then(() => {
            stateValReset();
            admissionUpdateSuccess('update');
          })
          .catch(err => setError(err));
      }
      return saveAdmission(data)
        .then(() => {
          stateValReset();
          admissionUpdateSuccess('add');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (!data.applicationNo) {
      errors.applicationNo = 'Application number cannot be empty';
    }
    if (!data.batchId) {
      errors.batchId = 'Batch cannot be empty';
    }
    if (!data.courseId) {
      errors.courseId = 'Course cannot be empty';
    }
    if (!data.firstName) {
      errors.firstName = 'First name cannot be empty';
    }
    if (!data.lastName) {
      errors.lastName = 'Last name cannot be empty';
    }
    if (!data.guardianEmail) {
      errors.guardianEmail = 'Email cannot be empty';
    } else if (!validator.isEmail(data.guardianEmail)) {
      errors.guardianEmail = 'Invalid email';
    }
    if (!data.phoneNumber) {
      errors.phoneNumber = 'Phone number cannot be empty';
    }
    if (!data.status) {
      errors.status = 'Status cannot be empty';
    }
    if (!data.gender) {
      errors.gender = 'Gender cannot be empty';
    }
    // older admissions may have no date of birth, so only a new one needs it
    if (!data.admissionId && !data.dateOfBirth) {
      errors.dateOfBirth = 'Date of birth cannot be empty';
    }
    if (!data.relation) {
      errors.relation = 'Relation cannot be empty';
    }
    if (!data.admissionId) {
      if (data.paymentAmount && !isValidPaymentAmount(data.paymentAmount)) {
        errors.paymentAmount = 'Enter the amount as a whole number greater than zero';
      } else if (!data.paymentAmount && data.paymentNote?.trim()) {
        errors.paymentAmount = 'Enter the amount for this note';
      }
    }
    // if (validator.isEmpty(data.gender)) {
    //   errors.gender = 'Gender cannot be empty';
    // }
    // if (validator.isEmpty(data.dateOfBirth.toString())) {
    //   errors.dateOfBirth = 'Date of birth cannot be empty';
    // } else if (moment(data.dateOfBirth) > moment().subtract(21, 'years')) {
    //   errors.dateOfBirth = 'Invalid date of birth, Minimum age should be 21';
    // }
    // if (validator.isEmpty(data.qualification)) {
    //   errors.qualification = 'Qualification cannot be empty';
    // }
    // if (validator.isEmpty(data.joiningDateTime.toString())) {
    //   errors.joiningDateTime = 'Joining date cannot be empty';
    // } else if (data.dateOfBirth >= data.joiningDateTime) {
    //   errors.joiningDateTime = "Joining date shouldn't be less than or equal to the Date of birth";
    // }
    // if (validator.isEmpty(data.designation)) {
    //   errors.designation = 'Designation type cannot be empty';
    // }
    // if (validator.isEmpty(data.department)) {
    //   errors.department = 'Department type cannot be empty';
    // }
    // if (validator.isEmpty(data.totalExperience)) {
    //   errors.totalExperience = 'Total experience cannot be empty';
    // }
    return errors;
  };

  const { data, errors, loading } = stateVal;
  const isDisabled = data?.admissionId;
  const thisData = (
    <Modal size="xl" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.admissionId ? 'UPDATE ADMISSION FORM' : 'ADD ADMISSION FORM'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              {/* <Row>
                  <Col sm={12}>
                    <FormGroup>
                      <Label htmlFor="">Select school<sup> *</sup></Label>
                        <Select
                          value={data.school.schoolId ? { label: data.school.label, value: data.school.value } : null}
                          onChange={(value) => handleSelectChange('school', value)}
                          options={schoolArr}
                        />
                        {errors.schoolId && <span className="err-msg">{errors.schoolId}</span>}
                      </FormGroup>
                  </Col>
                  </Row> */}
              <Row>
                <Col xs={12}>
                  <div
                    className="text-primary text-uppercase font-weight-bold mb-3 pb-1"
                    style={{ fontSize: 13, borderBottom: '1px solid #e3e3e3' }}>
                    Admission details
                  </div>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Batch<sup> *</sup>
                    </Label>
                    <CustomSelect
                      noLabel={true}
                      name="batchId"
                      value={data?.batchId}
                      onChange={handleSelectChange}
                      options={batchArr}
                      isDisabled={isDisabled}
                      applyLabelStyle={true}
                    />
                    {errors.batchId && <span className="err-msg">{errors.batchId}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Course<sup> *</sup>
                    </Label>
                    <CustomSelect
                      noLabel={true}
                      name="courseId"
                      value={data?.courseId}
                      onChange={handleSelectChange}
                      options={courseArr}
                      isDisabled={isDisabled}
                      applyLabelStyle={true}
                    />
                    {errors.courseId && <span className="err-msg">{errors.courseId}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Application number<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="applicationNo"
                      onChange={e => handleChange(e)}
                      value={data.applicationNo}
                      placeholder="Enter here..."
                      maxLength="50"
                      disabled={isDisabled}
                    />
                    {errors.applicationNo && <span className="err-msg">{errors.applicationNo}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Staff child?</Label>
                    <ChoiceChips
                      options={YES_NO}
                      value={data.isStaffChild}
                      onChange={value => handleSelectChange('isStaffChild', value)}
                    />
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Status</Label>
                    <Select
                      value={statusList?.find(el => el.value === data.status) || null}
                      onChange={e => handleSelectChange('status', e?.value)}
                      options={statusList}
                      isDisabled={!loggedUserRole || loggedUserRole !== constants.roles.admin}
                    />
                    {errors.status && <span className="err-msg">{errors.status}</span>}
                  </FormGroup>
                </Col>
              </Row>
              <Row className="mt-3">
                <Col xs={12}>
                  <div
                    className="text-primary text-uppercase font-weight-bold mb-3 pb-1"
                    style={{ fontSize: 13, borderBottom: '1px solid #e3e3e3' }}>
                    Student details
                  </div>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Student First name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="firstName"
                      onChange={e => handleChange(e)}
                      value={data.firstName}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.firstName && <span className="err-msg">{errors.firstName}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Student Last name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="lastName"
                      onChange={e => handleChange(e)}
                      value={data.lastName}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.lastName && <span className="err-msg">{errors.lastName}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Student Gender <sup>*</sup>
                    </Label>
                    <ChoiceChips
                      options={GENDERS}
                      value={data.gender}
                      onChange={value => handleSelectChange('gender', value)}
                    />
                    {errors.gender && <span className="err-msg">{errors.gender}</span>}
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup className="customDatePickerWidth">
                    <Label htmlFor="">
                      Student Date of Birth<sup> *</sup>
                    </Label>
                    <br />
                    <DatePicker
                      className="form-control"
                      selected={data.dateOfBirth ? new Date(data.dateOfBirth) : null}
                      onChange={value => handleDateChange('dateOfBirth', value)}
                      dateFormat="dd/MM/yyyy"
                      showMonthDropdown
                      showYearDropdown
                      placeholderText="Select date..."
                      dropdownMode="select"
                    />
                    {errors.dateOfBirth && <span className="err-msg">{errors.dateOfBirth}</span>}
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Academic year</Label>
                    <Input
                      type="text"
                      name="acadYear"
                      onChange={e => handleChange(e)}
                      value={data.acadYear}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Admission year</Label>
                    <Input
                      type="text"
                      name="admissionYear"
                      onChange={e => handleChange(e)}
                      value={data.admissionYear}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Birth place</Label>
                    <Input
                      type="text"
                      name="birthPlace"
                      onChange={e => handleChange(e)}
                      value={data.birthPlace}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Blood group</Label>
                    <Input
                      type="text"
                      name="bloodGroup"
                      onChange={e => handleChange(e)}
                      value={data.bloodGroup}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Mothertongue</Label>
                    <Input
                      type="text"
                      name="motherTongue"
                      onChange={e => handleChange(e)}
                      value={data.motherTongue}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Nationality</Label>
                    <Input
                      type="text"
                      name="nationality"
                      onChange={e => handleChange(e)}
                      value={data.nationality}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Religion</Label>
                    <Input
                      type="text"
                      name="religion"
                      onChange={e => handleChange(e)}
                      value={data.religion}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Student Physically challenged?</Label>
                    <ChoiceChips
                      options={YES_NO}
                      value={data.isPhysicallyChallenged}
                      onChange={value => handleSelectChange('isPhysicallyChallenged', value)}
                    />
                  </FormGroup>
                </Col>
              </Row>
              <Row className="mt-3">
                <Col xs={12}>
                  <div
                    className="text-primary text-uppercase font-weight-bold mb-3 pb-1"
                    style={{ fontSize: 13, borderBottom: '1px solid #e3e3e3' }}>
                    Guardian details
                  </div>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Guardian Email<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="guardianEmail"
                      onChange={e => handleChange(e)}
                      value={data.guardianEmail}
                      placeholder="Enter here..."
                      maxLength="50"
                      disabled={isDisabled}
                    />
                    {errors.guardianEmail && <span className="err-msg">{errors.guardianEmail}</span>}
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">
                      Guardian Phone<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="phoneNumber"
                      onChange={e => handleChange(e)}
                      value={data.phoneNumber}
                      placeholder="Enter here..."
                      maxLength="50"
                      disabled={isDisabled}
                    />
                    {errors.phoneNumber && <span className="err-msg">{errors.phoneNumber}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Guardian Relation type</Label>
                    <ChoiceChips
                      options={relationTypes}
                      value={data.relation}
                      onChange={value => handleSelectChange('relation', value)}
                    />
                    {errors.relation && <span className="err-msg">{errors.relation}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Guardian Education</Label>
                    <Input
                      type="text"
                      name="education"
                      onChange={e => handleChange(e)}
                      value={data.education}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Guardian Income</Label>
                    <Input
                      type="text"
                      name="income"
                      onChange={e => handleChange(e)}
                      value={data.income}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>{' '}
                </Col>
                <Col sm={6} md={4}>
                  <FormGroup>
                    <Label htmlFor="">Guardian Occupation</Label>
                    <Input
                      type="text"
                      name="occupation"
                      onChange={e => handleChange(e)}
                      value={data.occupation}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                </Col>
              </Row>
              {!data.admissionId && (
                <Row className="mt-3">
                  <Col xs={12}>
                    <div
                      className="text-primary text-uppercase font-weight-bold mb-3 pb-1"
                      style={{ fontSize: 13, borderBottom: '1px solid #e3e3e3' }}>
                      Admission payment (optional)
                    </div>
                  </Col>
                  <Col xs={12}>
                    <div
                      style={{
                        background: `${colors.accent}0d`,
                        border: `1px solid ${colors.accent}33`,
                        borderRadius: 12,
                        padding: '14px 14px 2px',
                      }}>
                      <p className="text-muted mb-3" style={{ fontSize: 12 }}>
                        Collect the admission fee now, or leave the amount empty and add the payment later from the
                        list.
                      </p>
                      <Row>
                        <Col sm={6} md={4}>
                          <FormGroup>
                            <Label htmlFor="">Amount</Label>
                            <InputGroup>
                              <InputGroupAddon addonType="prepend">
                                <InputGroupText>₹</InputGroupText>
                              </InputGroupAddon>
                              <Input
                                type="text"
                                inputMode="numeric"
                                name="paymentAmount"
                                onChange={e =>
                                  handleSelectChange('paymentAmount', e.target.value.replace(/\D/g, '').slice(0, 9))
                                }
                                value={data.paymentAmount}
                                placeholder="Optional..."
                              />
                            </InputGroup>
                            {errors.paymentAmount && <span className="err-msg">{errors.paymentAmount}</span>}
                          </FormGroup>
                        </Col>
                        <Col sm={12} md={8}>
                          <FormGroup>
                            <Label htmlFor="">Note</Label>
                            <Input
                              type="text"
                              name="paymentNote"
                              onChange={e => handleChange(e)}
                              value={data.paymentNote}
                              placeholder="Optional..."
                              maxLength={MAX_PAYMENT_NOTE}
                            />
                          </FormGroup>
                        </Col>
                      </Row>
                    </div>
                  </Col>
                </Row>
              )}
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton
            type="submit"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="secondary"
            disabled={loading}
            loading={loading}
          />
          <CustomButton
            className="ml-2"
            type="reset"
            style={{ fontWeight: 'bold' }}
            variant="contained"
            color="default"
            onClick={formModalClose}
            disabled={loading}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default AdmissionFormModal;
