import React from 'react';
import { CircularProgress } from '@material-ui/core';
import AddCircleOutlineIcon from '@material-ui/icons/AddCircleOutline';
import VisibilityIcon from '@material-ui/icons/Visibility';
import GetAppIcon from '@material-ui/icons/GetApp';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import ErrorOutlineIcon from '@material-ui/icons/ErrorOutline';
import colors from 'config/colors';
import { formatMoney } from 'utils/commonFunc';
import ListDropDown from '../../Common/ListDropDown';
import AdmissionStatusBadge, { Pill } from './AdmissionStatusBadge';

const PAID_COLOR = '#2e7d32';
const UNPAID_COLOR = '#b26a00';

const receiptLinkStyle = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 3,
  cursor: 'pointer',
  color: colors.accent,
};

const AdmissionList = ({
  admissionItem,
  fetchAdmission,
  deleteAdmission,
  viewAdmission,
  addPayment,
  viewReceipt,
  isReceiptLoading,
}) => {
  const hasBill = !!admissionItem?.customBillId;
  const isPaid = hasBill && admissionItem?.billStatus === 'PAID';
  return (
    <tr>
      <td>{admissionItem?.applicationNo}</td>
      <td>{`${admissionItem?.firstName} ${admissionItem?.lastName}`}</td>
      <td>{admissionItem?.guardianEmail}</td>
      <td>{admissionItem?.phoneNumber}</td>
      <td>{admissionItem?.relation}</td>
      <td>
        <AdmissionStatusBadge status={admissionItem?.status} />
      </td>
      <td style={{ whiteSpace: 'nowrap' }}>
        {!hasBill && (
          <>
            <Pill color={UNPAID_COLOR} Icon={ErrorOutlineIcon}>
              Unpaid
            </Pill>
            <div className="mt-1">
              <span onClick={() => addPayment(admissionItem)} style={receiptLinkStyle}>
                <AddCircleOutlineIcon style={{ fontSize: 16 }} />
                <b>Add payment</b>
              </span>
            </div>
          </>
        )}
        {hasBill && (
          <>
            <Pill color={isPaid ? PAID_COLOR : UNPAID_COLOR} Icon={isPaid ? CheckCircleIcon : ErrorOutlineIcon}>
              {`${formatMoney(admissionItem?.billAmount)} ${isPaid ? 'Paid' : admissionItem?.billStatus || ''}`.trim()}
            </Pill>
            {isPaid && (
              <div className="mt-1">
                {isReceiptLoading ? (
                  <CircularProgress size={15} />
                ) : (
                  <>
                    <span
                      onClick={() => viewReceipt(admissionItem, false)}
                      style={receiptLinkStyle}
                      title="View receipt">
                      <VisibilityIcon style={{ fontSize: 16 }} />
                      <b>View</b>
                    </span>
                    <span className="mx-2" style={{ color: '#c5cad3' }}>
                      |
                    </span>
                    <span
                      onClick={() => viewReceipt(admissionItem, true)}
                      style={receiptLinkStyle}
                      title="Download receipt">
                      <GetAppIcon style={{ fontSize: 16 }} />
                      <b>Download</b>
                    </span>
                  </>
                )}
              </div>
            )}
          </>
        )}
      </td>
      <td className="text-center">
        <ListDropDown
          actionList={['edit', 'view_as_user']}
          item={admissionItem}
          viewItem={() => viewAdmission(admissionItem.admissionId, admissionItem?.phoneNumber)}
          fetchItem={() => fetchAdmission(admissionItem?.admissionId)}
          deleteItem={() => deleteAdmission(admissionItem?.admissionId)}
        />
      </td>
    </tr>
  );
};

export default AdmissionList;
